components.css:
.ds-btn-primary {
  display: inline-block;
  width: 100%;
  font-family: var(--serif, Fraunces, Georgia, "Times New Roman", serif);
  font-weight: 600; font-size: 15px; letter-spacing: 0.04em;
  color: var(--ivory, #F6EDDD);
  background: var(--henna, #8C2E2A);
  text-align: center; text-decoration: none;
  padding: 14px 12px;
  border: none; border-radius: 2px; cursor: pointer;
  transition: background .18s ease-out, transform .18s ease-out;
}
.ds-btn-primary:hover { background: var(--inkbrown, #4A2C16); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--rust, #B04A2C); outline-offset: 2px; }
.ds-btn-primary:disabled { opacity: .6; cursor: default; }

.ds-appointment {
  border: 1px solid var(--sandline, #DDC9A8);
  background: var(--ivory, #F6EDDD);
  padding: 24px 26px 26px;
  display: flex; flex-direction: column; gap: 18px;
  box-shadow: inset 0 0 0 1px rgba(246,237,221,0.6), 0 14px 30px -22px rgba(74,44,22,0.4);
}
.ds-ahead {
  font-family: var(--serif, Fraunces, Georgia, serif);
  font-size: 11px; letter-spacing: .24em; text-transform: uppercase;
  color: var(--henna, #8C2E2A);
  display: flex; align-items: center; gap: 10px;
}
.ds-ahead::before { content: ""; width: 22px; height: 1px; background: var(--henna, #8C2E2A); }
.ds-date { display: grid; grid-template-columns: auto 1fr; gap: 2px 18px; align-items: baseline; font-size: 15px; color: var(--clay, #6B4A2A); }
.ds-date b { font-weight: 600; color: var(--inkbrown, #4A2C16); font-variant-numeric: tabular-nums; }
.ds-lbl { font-size: 11px; letter-spacing: .18em; text-transform: uppercase; color: var(--gold, #C29A4B); }
.ds-slot { font-size: 13px; color: var(--clay, #6B4A2A); display: flex; align-items: center; gap: 8px; }
.ds-slot i { font-style: normal; color: var(--henna, #8C2E2A); font-variant-numeric: tabular-nums; }
.ds-slot::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--henna, #8C2E2A); flex: none; }
.ds-instock { display: flex; align-items: center; justify-content: space-between; font-size: 13px; color: var(--clay, #6B4A2A); }
.ds-ticks { letter-spacing: .34em; color: var(--henna, #8C2E2A); font-variant-numeric: tabular-nums; }

.ds-service { padding: 16px 0 18px; border-bottom: 1px solid var(--sandline, #DDC9A8); }
.ds-service:last-child { border-bottom: none; }
.ds-service h3 {
  font-family: var(--serif, Fraunces, Georgia, serif);
  font-weight: 600; font-size: clamp(20px, 3.4vw, 24px);
  color: var(--inkbrown, #4A2C16);
  display: flex; align-items: baseline; gap: 10px; text-wrap: balance;
  margin: 0;
}
.ds-n { font-size: 13px; color: var(--gold, #C29A4B); font-weight: 500; letter-spacing: .1em; }
.ds-service p { font-family: var(--serif, Fraunces, Georgia, serif); font-size: 15px; color: var(--clay, #6B4A2A); margin: 7px 0 0; max-width: 38ch; }
.ds-note { font-family: var(--serif, Fraunces, Georgia, serif); font-size: 13px; font-style: italic; color: var(--henna, #8C2E2A); margin-top: 8px; }

.ds-masthead { display: flex; align-items: baseline; gap: 48px; border-bottom: 2px solid var(--inkbrown, #4A2C16); padding-bottom: 18px; }
.ds-masthead h1 { font-family: var(--serif, Fraunces, Georgia, serif); font-weight: 600; font-size: clamp(28px, 4.5vw, 44px); line-height: .95; letter-spacing: -0.01em; text-wrap: balance; color: var(--inkbrown, #4A2C16); margin: 0; }
.ds-henna { color: var(--henna, #8C2E2A); }
.ds-masthead h1 em { font-style: italic; font-weight: 400; }
.ds-folio { margin-left: auto; text-align: right; font-family: var(--serif, Fraunces, Georgia, serif); font-size: 13px; letter-spacing: .14em; text-transform: uppercase; color: var(--clay, #6B4A2A); white-space: nowrap; }
.ds-folio b { display: block; font-weight: 600; color: var(--henna, #8C2E2A); font-size: 16px; font-variant-numeric: tabular-nums; }

.ds-house { border-top: 2px solid var(--inkbrown, #4A2C16); padding-top: 26px; display: flex; justify-content: space-between; align-items: baseline; gap: 24px; }
.ds-c2 { font-family: var(--serif, Fraunces, Georgia, serif); font-size: clamp(22px, 3.6vw, 30px); font-weight: 600; color: var(--henna, #8C2E2A); text-decoration: underline; text-decoration-color: var(--rust, #B04A2C); text-decoration-thickness: 2px; text-underline-offset: 6px; text-wrap: balance; margin: 0; }
.ds-attr { margin-left: auto; font-family: var(--serif, Fraunces, Georgia, serif); font-size: 13px; letter-spacing: .14em; text-transform: uppercase; color: var(--clay, #6B4A2A); text-align: right; }
.ds-attr b { display: block; font-weight: 600; color: var(--inkbrown, #4A2C16); font-size: 16px; white-space: nowrap; font-variant-numeric: tabular-nums; }

.ds-ruled-page {
  background: linear-gradient(rgba(74,44,22,0.048) 1px, transparent 1px) 0 0 / 100% 34px, var(--paper, #FBF4E7);
  border: 1px solid var(--sandline, #DDC9A8);
  padding: 64px;
  box-shadow: 0 1px 0 rgba(74,44,22,0.08), 0 18px 40px -24px rgba(74,44,22,0.35);
  position: relative;
}
.ds-ruled-page::before {
  content: ""; position: absolute; left: 20px; top: 0; bottom: 0; width: 1px;
  background: linear-gradient(rgba(74,44,22,0.12) 2px, transparent 2px);
  background-size: 100% 34px;
}
.ds-ruled-page::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 160px;
  background: linear-gradient(to top, rgba(74,44,22,0.05), transparent);
  pointer-events: none;
}
.ds-ruled-page p { font-family: var(--serif, Fraunces, Georgia, serif); font-size: 16px; line-height: 1.55; color: var(--clay, #6B4A2A); max-width: 46ch; margin: 0; }

.ds-stain { margin: 34px 0 0; border-top: 1px solid var(--sandline, #DDC9A8); padding-top: 20px; overflow: hidden; }
.ds-stain-wrap { display: flex; align-items: center; justify-content: space-between; gap: 18px; flex-wrap: wrap; }
.ds-stain-line { font-family: var(--serif, Fraunces, Georgia, serif); font-size: 16px; font-style: italic; color: var(--clay, #6B4A2A); max-width: 46ch; margin: 0; }
.ds-stain-mark { flex: none; width: 118px; height: 58px; }
.ds-stain-state { font-family: var(--serif, Fraunces, Georgia, serif); font-size: 12.5px; letter-spacing: .18em; text-transform: uppercase; color: var(--clay, #6B4A2A); width: 100%; text-align: right; margin-top: 10px; }
